# 07_figure6.R: Figure 6 candidates (PDF + SVG + PNG). Usage: Rscript 07_figure6.R  (main: surfaces at order 3; alternative: order 5)
source("lib6.R"); suppressMessages({library(ggplot2); library(patchwork)}); dir.create("figures", FALSE)
pal <- c(petrol = "#1F5F6B", orange = "#C8641E", sage = "#8AA37B", grey = "#7A7F85")
grp_lab <- c(BM = "Macroinvertebrates", ZP = "Zooplankton", PP = "Phytoplankton"); grp_col <- c(Macroinvertebrates = pal[["petrol"]], Zooplankton = pal[["orange"]], Phytoplankton = pal[["sage"]])
comp_lab <- c(total = "Total", occupancy = "Occupancy-\nassociated", heterogeneity = "Abundance\nheterogeneity"); th <- function(b = 7) theme_classic(base_size = b) + theme(panel.grid = element_blank(), strip.background = element_blank(), strip.text = element_text(face = "bold", size = b), legend.key.size = unit(3, "mm"), legend.margin = margin(0, 0, 0, 0), plot.tag = element_text(face = "bold", size = 9), axis.line = element_line(linewidth = .3), axis.ticks = element_line(linewidth = .3))
# ---- A: gradients and informative orders
env <- bind_rows(lapply(names(D), function(g) data.frame(group = grp_lab[[g]], TP = D[[g]]$env$TP, n = nrow(D[[g]]$x)))); env$group <- factor(env$group, grp_lab); nlab <- env |> group_by(group) |> summarise(n = first(n), .groups = "drop") |> mutate(lab = sprintf("n = %d", n))
bands <- data.frame(xmin = log10(c(1, 10, 35, 100)), xmax = log10(c(10, 35, 100, 20000)), cls = factor(c("Oligotrophic", "Mesotrophic", "Eutrophic", "Hypereutrophic"), c("Oligotrophic", "Mesotrophic", "Eutrophic", "Hypereutrophic")))
pA1 <- ggplot(env, aes(log10(TP), colour = group, fill = group)) + geom_rect(data = bands, aes(xmin = xmin, xmax = xmax, ymin = -Inf, ymax = Inf), inherit.aes = FALSE, fill = c("#EEF3F0", "#FFFFFF", "#F3EEE9", "#FFFFFF"), colour = NA) +
  geom_density(alpha = .25, linewidth = .5, adjust = 1.2) + geom_text(data = nlab, aes(x = 3.85, y = c(.62, .52, .42)[as.integer(group)], label = paste(group, lab)), inherit.aes = FALSE, colour = unname(grp_col[as.character(nlab$group)]), hjust = 1, size = 2.3) +
  scale_x_continuous(breaks = log10(c(3, 10, 35, 100, 1000, 10000)), labels = c(3, 10, 35, 100, "1,000", "10,000"), limits = c(.1, 4)) + scale_colour_manual(values = grp_col, guide = "none") + scale_fill_manual(values = grp_col, guide = "none") +
  annotate("text", x = log10(c(5.5, 19, 58, 400)), y = Inf, label = c("oligo", "meso", "eutro", "hyper"), vjust = 1.4, size = 2, colour = pal[["grey"]]) + labs(x = expression("Total phosphorus (" * mu * "g" ~ L^-1 * ", log scale)"), y = "Density") + th()
oi <- read.csv("tables/order_information.csv") |> filter(response == "relative") |> mutate(group = factor(grp_lab[group], grp_lab)); ORD <- list(BM = c(2, 3, 4, 5, 6, 8, 10), ZP = c(2, 3, 4, 5, 6), PP = c(2, 3, 4, 5)); oi$modelled <- mapply(function(g, o) o %in% ORD[[names(grp_lab)[grp_lab == g]]], as.character(oi$group), oi$order)
pA2 <- ggplot(oi, aes(order, sharing_probability, colour = group)) + geom_hline(yintercept = .1, linetype = 2, linewidth = .3, colour = pal[["grey"]]) + geom_line(linewidth = .5) + geom_point(aes(shape = modelled, fill = ifelse(modelled, as.character(group), NA)), size = 1.8, stroke = .5) + scale_shape_manual(values = c(`TRUE` = 21, `FALSE` = 1), guide = "none") +
  scale_colour_manual(values = grp_col, name = NULL) + scale_fill_manual(values = grp_col, na.value = NA, guide = "none") + scale_y_log10(limits = c(.002, 1), breaks = c(.003, .01, .03, .1, .3, 1), labels = c("0.003", "0.01", "0.03", "0.1", "0.3", "1")) + scale_x_continuous(breaks = c(2, 4, 6, 8, 10, 15, 20, 30), trans = "sqrt") + labs(x = "Zeta order k", y = "P(shared species)\nacross k randomly drawn lakes") + th() + theme(legend.position = "none")
# ---- B: importance
imp <- read.csv("tables/importance_predictor.csv") |> filter(chla, penalty == "0.01") |> mutate(group = factor(grp_lab[group], grp_lab), response = factor(comp_lab[response], comp_lab), predictor = factor(predictor, c("TP", "TN", "Chla", "geographic_distance"), c("TP", "TN", "Chl-a", "Geographic distance")))
pcol <- c(TP = pal[["petrol"]], TN = pal[["orange"]], `Chl-a` = pal[["sage"]], `Geographic distance` = pal[["grey"]])
pB <- ggplot(imp, aes(order, absolute_mean, colour = predictor, fill = predictor, group = predictor)) + geom_hline(yintercept = 0, linewidth = .3, colour = "grey70") + geom_line(linewidth = .5) + geom_point(size = 1) +
  facet_grid(response ~ group, scales = "free_x") + scale_colour_manual(values = pcol, name = NULL) + scale_fill_manual(values = pcol, guide = "none") + scale_x_continuous(breaks = c(2, 3, 4, 5, 6, 8, 10)) + labs(x = "Zeta order k", y = expression("Held-out attribution (" * Delta * D^2 * ")")) + th() + theme(legend.position = "bottom", strip.text.y = element_text(size = 6))
# ---- C: context-dependent TP spread effects
mkC <- function(k) { sur <- read.csv("tables/panelC_predictions.csv") |> filter(order == k, model %in% c("additive", "interaction_pen1e-4")) |> pivot_longer(c(total, occupancy, heterogeneity), names_to = "component", values_to = "pred") |>
    mutate(group = factor(grp_lab[group], grp_lab), component = factor(comp_lab[component], comp_lab), trophic = factor(trophic, c("Oligotrophic", "Mesotrophic", "Eutrophic")), lab = sprintf("%s (TP %s)", trophic, "")) 
  ggplot(sur, aes(spread, pred, colour = trophic, linetype = model, linewidth = model, group = interaction(trophic, model))) + geom_line() + geom_point(data = sur |> filter(model == "additive"), size = .9) + facet_grid(component ~ group, scales = "free") +
    scale_colour_manual(values = c(Oligotrophic = pal[["sage"]], Mesotrophic = pal[["petrol"]], Eutrophic = pal[["orange"]]), name = "TP position") + scale_linetype_manual(values = c(additive = 1, `interaction_pen1e-4` = 3), labels = c("Additive (position + spread)", "Explicit interaction (penalty 1e-4)"), name = NULL) + scale_linewidth_manual(values = c(additive = .6, `interaction_pen1e-4` = .5), guide = "none") +
    labs(x = expression("Spread: mean pairwise difference in log"[10] * " TP (common supported range)"), y = "Predicted dissimilarity") + th() + theme(legend.position = "bottom", legend.box = "vertical", strip.text.y = element_text(size = 6)) + guides(colour = guide_legend(order = 1), linetype = guide_legend(order = 2)) }
# ---- D: added value
gn <- read.csv("tables/validation_gains.csv") |> filter(chla) |> mutate(group = factor(grp_lab[group], grp_lab), component = factor(comp_lab[component], comp_lab))
pen <- read.csv("tables/interaction_penalty_sensitivity.csv") |> filter(pen == 1e-4) |> mutate(group = factor(grp_lab[group], grp_lab), component = factor(comp_lab[component], comp_lab))
dd <- bind_rows(gn |> transmute(group, component, order, effect = "Nonlinear position (additive - spread only)", med = position_med, lo = position_lo, hi = position_hi),
                gn |> transmute(group, component, order, effect = "Explicit interaction (default penalty - additive)", med = interaction_med, lo = interaction_lo, hi = interaction_hi),
                pen |> transmute(group, component, order, effect = "Explicit interaction (penalty 1e-4 - additive)", med = gain_median, lo = gain_min, hi = gain_max)) |> mutate(effect = factor(effect, c("Nonlinear position (additive - spread only)", "Explicit interaction (default penalty - additive)", "Explicit interaction (penalty 1e-4 - additive)")))
pD <- ggplot(dd, aes(order, med, colour = group, fill = group)) + geom_hline(yintercept = 0, linewidth = .3, colour = "grey70") + geom_linerange(aes(ymin = lo, ymax = hi), linewidth = .3, alpha = .5, position = position_dodge(width = .35)) + geom_line(linewidth = .5, position = position_dodge(width = .35)) + geom_point(size = 1, position = position_dodge(width = .35)) + facet_grid(effect ~ component, scales = "free_y", labeller = labeller(effect = label_wrap_gen(24))) +
  scale_colour_manual(values = grp_col, name = NULL) + scale_fill_manual(values = grp_col, guide = "none") + scale_x_continuous(breaks = c(2, 4, 6, 8, 10)) + labs(x = "Zeta order k", y = expression("Change in held-out spatial-block " * D^2)) + th() + theme(legend.position = "bottom", strip.text.y = element_text(size = 5.5))
build <- function(k, tag) { PA <- (pA1 | pA2) + plot_layout(widths = c(1.35, 1), tag_level = "new"); fig <- wrap_plots(PA, pB, mkC(k), pD, ncol = 1, heights = c(1.0, 2.0, 2.3, 2.3)) + plot_annotation(tag_levels = list(c("A", "B", "C", "D"), "a"), tag_sep = "") & theme(plot.tag = element_text(face = "bold", size = 9))
  for (e in c("pdf", "svg", "png")) ggsave(sprintf("figures/%s.%s", tag, e), fig, width = 7.4, height = 11.6, dpi = 220, device = if (e == "pdf") cairo_pdf else NULL) }
build(3, "Figure6_main_order3"); build(5, "Figure6_alt_order5"); cat("done\n")
